// Update a primitive field
return { ...state, count: state.count + 1 };

// Append to an array
return { ...state, items: [...state.items, newItem] };

// Remove from an array
return {
  ...state,
  items: state.items.filter(item => item.id !== idToRemove)
};

// Update one item in an array
return {
  ...state,
  items: state.items.map(item =>
    item.id === targetId ? { ...item, completed: !item.completed } : item
  )
};

// Update a nested object
return {
  ...state,
  user: {
    ...state.user,
    profile: {
      ...state.user.profile,
      name: 'New Name'
    }
  }
};

// Update one item in a nested array
return {
  ...state,
  posts: state.posts.map(post =>
    post.id === id ? { ...post, title: 'Updated title' } : post
  )
};

function badReducer(state, action) {
  if (action.type === 'ADD_TODO') {
    state.todos.push(action.payload);
  }
  if (action.type === 'TOGGLE_TODO') {
    const todo = state.todos.find(t => t.id === action.payload.id);
    todo.completed = !todo.completed;
  }
  return state;
}
